import csv
from collections import defaultdict

def analyze(f):
    with open(f, newline='') as fh:
        rd = list(csv.reader(fh))
    if not rd:
        print(f, 'EMPTY'); return
    hdr = [h.strip().lower() for h in rd[0]]
    print('==', f)
    print('HDR:', hdr)
    if len(rd) > 1: print('ROW0:', rd[1])
    def find(*keys):
        for i,h in enumerate(hdr):
            if all(k in h for k in keys): return i
        for i,h in enumerate(hdr):
            if keys[0] in h: return i
        return None
    yi = find('year'); ai = find('actual'); ei = find('expected')
    if yi is None or ai is None or ei is None:
        print('cannot parse columns'); return
    tot = defaultdict(lambda: [0.0,0.0]); hi = defaultdict(lambda: [0,0])
    for r in rd[1:]:
        if len(r) <= max(yi,ai,ei): continue
        try:
            y = int(float(r[yi])); a = float(r[ai]); e = float(r[ei])
        except Exception:
            continue
        tot[y][0]+=a; tot[y][1]+=e
        if e >= 10:
            hi[y][1]+=1
            if e > 0 and a/e > 1.2: hi[y][0]+=1
    for y in sorted(tot):
        a,e = tot[y]; h,n = hi[y]
        print(y, 'recon_AE=%.3f' % (a/e if e else 0), 'cells_e>=10=%d  cells_AE>1.2=%d' % (n,h))

for f in ['ae_tpd_age_gender.csv','ae_ip_age_gender.csv','ae_death_age_gender.csv','ae_ci_age_gender.csv']:
    try:
        analyze(f)
    except Exception as ex:
        print(f, 'ERROR', ex)
